-- ---------------------------------------------------- Çevrilmeyenler
insert into public.ceviri_atlanan (question_id, dil, neden, kod)
select q.id, 'en', v.neden, 'cevrilemez'
  from (values
  ('Baharın gelişini kutlayan Hıdırellez her yıl hangi tarihte kutlanır?', 'Türkiye''ye özgü bir gelenek günü; İngilizce oyuncu için bağlamsız, çevirisi anlamlı bir bilgi sorusu üretmiyor.'),
  ('''Türk Yıldız Savaşları'' diye de anılan ''Dünyayı Kurtaran Adam'' (1982) filminin başrol oyuncusu kimdir?', 'Yeşilçam''a özgü, İngilizce oyuncu için bağlamı olmayan yerel bir popüler kültür sorusu; çevirisi anlamlı bir bilgi sorusu üretmiyor.'),
  ('''Hababam Sınıfı'' filmlerinde öğrencilerin sevgili öğretmeni Mahmut Hoca''yı canlandıran usta oyuncu kimdir?', 'Yalnızca Türk izleyicinin tanıdığı Yeşilçam karakteri ve oyuncusu; İngilizce oyuncu için bağlamsız.'),
  ('''Tamirci Çırağı'' ve ''Resimdeki Gözyaşları'' şarkılarıyla tanınan Anadolu rock sanatçısı kimdir?', 'Soru Türkçe şarkı adlarına dayanıyor; İngilizce oyuncu için şarkı adları anlamsız, çevirisi anlamlı bir soru üretmiyor.')
  ) v(soru, neden)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Karıştırma (TR + EN aynı permütasyon)
drop table if exists pg_temp._parti_karistir;
create temp table _parti_karistir as
select q.id, array_agg(s.idx order by s.rnd) as perm
  from public.questions q
  cross join lateral (
    select (ordinality - 1)::int as idx, random() as rnd
      from jsonb_array_elements(q.secenekler) with ordinality
  ) s
 where q.created_at >= transaction_timestamp()
 group by q.id;

update public.questions q
   set secenekler = (select jsonb_agg(q.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o)),
       dogru_cevap = (array_position(k.perm, q.dogru_cevap::int) - 1)::smallint
  from _parti_karistir k
 where q.id = k.id;

update public.question_translations t
   set secenekler = (select jsonb_agg(t.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o))
  from _parti_karistir k
 where t.question_id = k.id;

drop table if exists pg_temp._parti_karistir;
